<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use App\Models\Event;
use App\Models\EventImage;

class EventSeeder extends Seeder
{
    public function run()
    {
        $images = [
            '',
            '',
            '',
            '',
            '',
        ];

        for ($i = 1; $i <= 5; $i++) {
            $random = random_int(0, 4);
            $event = Event::create([
                'name' => "Event $i",
                'description' => "Description for event $i",
                'scheduled_time' => now()->addDays($i),
                'capacity' => rand(50, 200),
                'price' => rand(0, 500),
                'status' => 'planned',
            ]);

            // Add one head image
            EventImage::create([
                'event_id' => $event->id,
                'base64' => $images[$random],
                'is_head' => true,
            ]);

            // Add two more images
            for ($j = 1; $j <= 2; $j++) {
                $random = random_int(0, 4);
                EventImage::create([
                    'event_id' => $event->id,
                    'base64' => $images[$random],
                    'is_head' => false,
                ]);
            }
        }
    }
}
